12	/// A light wrapper around timeline items returned from Rust.
13	enum TimelineItemProxy {
14	    case event(EventTimelineItemProxy)
15	    case virtual(MatrixRustSDK.VirtualTimelineItem, uniqueID: TimelineItemIdentifier.UniqueID)
16	    case unknown(MatrixRustSDK.TimelineItem)
17	    
18	    init(item: MatrixRustSDK.TimelineItem) {
19	        if let eventItem = item.asEvent() {
20	            self = .event(EventTimelineItemProxy(item: eventItem, uniqueID: .init(rustValue: item.uniqueId())))
21	        } else if let virtualItem = item.asVirtual() {
22	            self = .virtual(virtualItem, uniqueID: .init(rustValue: item.uniqueId()))
23	        } else {
24	            self = .unknown(item)
25	        }
26	    }
27	    
28	    var isEvent: Bool {
29	        switch self {
30	        case .event:
31	            return true
32	        default:
33	            return false
34	        }
35	    }
36	}
37	
38	/// The delivery status for the item.
39	enum TimelineItemDeliveryStatus: Hashable {
40	    case sending
41	    case sent
42	    case sendingFailed(TimelineItemSendFailure)
43	    
44	    var isSendingFailed: Bool {
45	        switch self {
46	        case .sending, .sent: false
47	        case .sendingFailed: true
48	        }
49	    }
50	}
51	
52	/// The reason a timeline item failed to send.
53	enum TimelineItemSendFailure: Hashable {
54	    enum VerifiedUser: Hashable {
55	        case hasUnsignedDevice(devices: [String: [String]])
56	        case changedIdentity(users: [String])
57	        
58	        var affectedUserIDs: [String] {
59	            switch self {
60	            case .hasUnsignedDevice(let devices): Array(devices.keys)
61	            case .changedIdentity(let users): users
62	            }
63	        }
64	    }
65	    
66	    case verifiedUser(VerifiedUser)
67	    case unknown
68	}
69	
70	/// A light wrapper around event timeline items returned from Rust.
71	class EventTimelineItemProxy {
72	    let item: MatrixRustSDK.EventTimelineItem
73	    let id: TimelineItemIdentifier
74	    
75	    init(item: MatrixRustSDK.EventTimelineItem, uniqueID: TimelineItemIdentifier.UniqueID) {
76	        self.item = item
77	        
78	        id = .event(uniqueID: uniqueID, eventOrTransactionID: .init(rustValue: item.eventOrTransactionId))
79	    }
80	    
81	    lazy var deliveryStatus: TimelineItemDeliveryStatus? = {
82	        guard let localSendState = item.localSendState else {
83	            return nil
84	        }
85	        
86	        switch localSendState {
87	        case .sendingFailed(let error, let isRecoverable):
88	            switch error {
89	            case .identityViolations(let users):
90	                return .sendingFailed(.verifiedUser(.changedIdentity(users: users)))
91	            case .insecureDevices(let userDeviceMap):
92	                return .sendingFailed(.verifiedUser(.hasUnsignedDevice(devices: userDeviceMap)))
93	            default:
94	                return .sendingFailed(.unknown)
95	            }
96	        case .notSentYet:
97	            return .sending
98	        case .sent:
99	            return .sent
100	        }
